def __init__(self):
    super().__init__()
    self.gamma = nn.Parameter(torch.tensor(1.702))
    self.beta = nn.Parameter(torch.tensor(0.1))

def forward(self, x):
    g = self.gamma.clamp(0.5, 10.0)
    b = self.beta.clamp(-0.1, 0.5)
    return x * (b + (1.0 - b) * torch.sigmoid(g * x))

